GParamSpec*
param_spec_configuration (const gchar* name,
                          const gchar* nick,
                          const gchar* blurb,
                          GType object_type,
                          GParamFlags flags)
{
	ParamSpecConfiguration* spec;
	g_return_val_if_fail (g_type_is_a (object_type, TYPE_CONFIGURATION), NULL);
	spec = g_param_spec_internal (G_TYPE_PARAM_OBJECT, name, nick, blurb, flags);
	G_PARAM_SPEC (spec)->value_type = object_type;
	return G_PARAM_SPEC (spec);
}

gpointer
value_get_configuration (const GValue* value)
{
	g_return_val_if_fail (G_TYPE_CHECK_VALUE_TYPE (value, TYPE_CONFIGURATION), NULL);
	return value->data[0].v_pointer;
}

void
value_set_configuration (GValue* value,
                         gpointer v_object)
{
	Configuration * old;
	g_return_if_fail (G_TYPE_CHECK_VALUE_TYPE (value, TYPE_CONFIGURATION));
	old = value->data[0].v_pointer;
	if (v_object) {
		g_return_if_fail (G_TYPE_CHECK_INSTANCE_TYPE (v_object, TYPE_CONFIGURATION));
		g_return_if_fail (g_value_type_compatible (G_TYPE_FROM_INSTANCE (v_object), G_VALUE_TYPE (value)));
		value->data[0].v_pointer = v_object;
		configuration_ref (value->data[0].v_pointer);
	} else {
		value->data[0].v_pointer = NULL;
	}
	if (old) {
		configuration_unref (old);
	}
}

void
value_take_configuration (GValue* value,
                          gpointer v_object)
{
	Configuration * old;
	g_return_if_fail (G_TYPE_CHECK_VALUE_TYPE (value, TYPE_CONFIGURATION));
	old = value->data[0].v_pointer;
	if (v_object) {
		g_return_if_fail (G_TYPE_CHECK_INSTANCE_TYPE (v_object, TYPE_CONFIGURATION));
		g_return_if_fail (g_value_type_compatible (G_TYPE_FROM_INSTANCE (v_object), G_VALUE_TYPE (value)));
		value->data[0].v_pointer = v_object;
	} else {
		value->data[0].v_pointer = NULL;
	}
	if (old) {
		configuration_unref (old);
	}
}

static void
configuration_class_init (ConfigurationClass * klass,
                          gpointer klass_data)
{
	configuration_parent_class = g_type_class_peek_parent (klass);
	((ConfigurationClass *) klass)->finalize = configuration_finalize;
	g_type_class_adjust_private_offset (klass, &Configuration_private_offset);
}

static void
configuration_instance_init (Configuration * self,
                             gpointer klass)
{
	self->priv = configuration_get_instance_private (self);
	self->ref_count = 1;
}

static void
configuration_finalize (Configuration * obj)
{
	Configuration * self;
	GError* _inner_error0_ = NULL;
	self = G_TYPE_CHECK_INSTANCE_CAST (obj, TYPE_CONFIGURATION, Configuration);
	g_signal_handlers_destroy (self);
	if (self->priv->config_changed) {
		configuration_save_config (self, &_inner_error0_);
		if (G_UNLIKELY (_inner_error0_ != NULL)) {
			g_critical ("file %s: line %d: uncaught error: %s (%s, %d)", __FILE__, __LINE__, _inner_error0_->message, g_quark_to_string (_inner_error0_->domain), _inner_error0_->code);
			g_clear_error (&_inner_error0_);
		}
	}
	_g_key_file_unref0 (self->priv->keyfile);
	_g_free0 (self->priv->config_file);
}

static GType
configuration_get_type_once (void)
{
	static const GTypeValueTable g_define_type_value_table = { value_configuration_init, value_configuration_free_value, value_configuration_copy_value, value_configuration_peek_pointer, "p", value_configuration_collect_value, "p", value_configuration_lcopy_value };
	static const GTypeInfo g_define_type_info = { sizeof (ConfigurationClass), (GBaseInitFunc) NULL, (GBaseFinalizeFunc) NULL, (GClassInitFunc) configuration_class_init, (GClassFinalizeFunc) NULL, NULL, sizeof (Configuration), 0, (GInstanceInitFunc) configuration_instance_init, &g_define_type_value_table };
	static const GTypeFundamentalInfo g_define_type_fundamental_info = { (G_TYPE_FLAG_CLASSED | G_TYPE_FLAG_INSTANTIATABLE | G_TYPE_FLAG_DERIVABLE | G_TYPE_FLAG_DEEP_DERIVABLE) };
	GType configuration_type_id;
	configuration_type_id = g_type_register_fundamental (g_type_fundamental_next (), "Configuration", &g_define_type_info, &g_define_type_fundamental_info, 0);
	Configuration_private_offset = g_type_add_instance_private (configuration_type_id, sizeof (ConfigurationPrivate));
	return configuration_type_id;
}

GType
configuration_get_type (void)
{
	static volatile gsize configuration_type_id__once = 0;
	if (g_once_init_enter (&configuration_type_id__once)) {
		GType configuration_type_id;
		configuration_type_id = configuration_get_type_once ();
		g_once_init_leave (&configuration_type_id__once, configuration_type_id);
	}
	return configuration_type_id__once;
}

gpointer
configuration_ref (gpointer instance)
{
	Configuration * self;
	self = instance;
	g_atomic_int_inc (&self->ref_count);
	return instance;
}

void
configuration_unref (gpointer instance)
{
	Configuration * self;
	self = instance;
	if (g_atomic_int_dec_and_test (&self->ref_count)) {
		CONFIGURATION_GET_CLASS (self)->finalize (self);
		g_type_free_instance ((GTypeInstance *) self);
	}
}

